import keyword


def is_valid_collection_name(value):
    if not isinstance(value, str):
        return False
    parts = value.split(".")
    if len(parts) != 2:
        return False
    for part in parts:
        if not part.isidentifier():
            return False
        if keyword.iskeyword(part):
